-- Finalised Lab/Glass requirements, versioned Parts issues and classified returns.
begin;
do $$begin if public.get_lab_delay_version() is distinct from '20261024-lab-delay-1' then raise exception 'Verified Lab Delay support is required.';end if;if to_regprocedure('public.get_parts_flow_version()') is not null then if public.get_parts_flow_version() is distinct from '20261026-parts-flow-1' then raise exception 'Existing Parts Flow needs review.';end if;end if;end;$$;
create table if not exists greenloop_private.parts_flow_orders(id uuid primary key default gen_random_uuid(),job_id uuid not null,device_id uuid not null,step_id uuid not null,cycle integer not null,revision integer not null default 1,services jsonb not null default '[]',submitted_at timestamptz not null default now(),submitted_by uuid,first_issued_at timestamptz,completed_at timestamptz,legacy boolean not null default false,unique(job_id,cycle));
create table if not exists greenloop_private.parts_flow_requests(request_id uuid primary key,order_id uuid not null references greenloop_private.parts_flow_orders(id));
create table if not exists greenloop_private.parts_flow_prices(issue_id uuid primary key,order_id uuid not null references greenloop_private.parts_flow_orders(id),unit_price numeric(12,2) check(unit_price>=0),currency text not null default 'AED',recorded_at timestamptz not null default now());
create table if not exists greenloop_private.parts_flow_returns(id uuid primary key default gen_random_uuid(),order_id uuid not null references greenloop_private.parts_flow_orders(id),issue_id uuid not null,quantity integer not null check(quantity>0),notes text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),classification text check(classification in ('not_needed','damaged','faulty')),replacement boolean not null default false,requested_by uuid,requested_at timestamptz not null default now(),reviewed_by uuid,reviewed_at timestamptz,review_notes text);
create table if not exists greenloop_private.parts_flow_stock(part_key text primary key,inventory_id uuid not null unique);
create table if not exists greenloop_private.parts_flow_audit(id uuid primary key default gen_random_uuid(),order_id uuid,action text not null,actor uuid,created_at timestamptz not null default now(),details jsonb not null default '{}');
create table if not exists greenloop_private.parts_flow_context(pid integer not null,tx bigint not null,actor uuid,primary key(pid,tx));
do $$declare t text;begin foreach t in array array['parts_flow_orders','parts_flow_requests','parts_flow_prices','parts_flow_returns','parts_flow_stock','parts_flow_audit','parts_flow_context']loop execute format('alter table greenloop_private.%I enable row level security',t);execute format('revoke all on greenloop_private.%I from public,anon,authenticated',t);end loop;end;$$;
create index if not exists parts_flow_request_order_idx on greenloop_private.parts_flow_requests(order_id);
create index if not exists parts_flow_price_order_idx on greenloop_private.parts_flow_prices(order_id);
create index if not exists parts_flow_return_order_idx on greenloop_private.parts_flow_returns(order_id,status);
create index if not exists parts_flow_audit_order_idx on greenloop_private.parts_flow_audit(order_id,created_at);
create or replace function greenloop_private.pf_cap(p_page text,p_cap text) returns void language plpgsql stable security definer set search_path=pg_catalog,public as $$begin perform greenloop_private.require_office_network();if greenloop_private.damage_tv_only(auth.uid()) or not coalesce(public.has_page_capability_v1(p_page,p_cap),false) then raise exception 'This Parts action is not allowed.' using errcode='42501';end if;end;$$;
create or replace function greenloop_private.pf_cycle(p_job uuid) returns integer language sql stable security definer set search_path=pg_catalog,public as $$select count(*)::integer from greenloop_private.lab_stays_v1((select device_id from public.jobs where id=p_job)) where job_id=p_job;$$;
create or replace function greenloop_private.pf_context(p_start boolean) returns void language plpgsql security definer set search_path=pg_catalog,public as $$begin if p_start then insert into greenloop_private.parts_flow_context values(pg_backend_pid(),txid_current(),auth.uid())on conflict do nothing;else delete from greenloop_private.parts_flow_context where pid=pg_backend_pid() and tx=txid_current();end if;end;$$;
create or replace function greenloop_private.pf_step(p_step uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$declare j uuid;begin perform pg_advisory_xact_lock(19920261026);select w.job_id into j from public.job_work_order_steps s join public.job_work_orders w on w.id=s.work_order_id join public.jobs job on job.id=w.job_id and job.deleted_at is null join public.devices d on d.id=w.device_id and d.deleted_at is null where s.id=p_step and s.department in ('laboratory','glass') and s.step_status='in_progress' and job.current_status in ('laboratory_pending','laboratory_in_progress','glass_pending','glass_in_progress') for update of s,job;if j is null then raise exception 'This Lab / Glass line is no longer active.' using errcode='22023';end if;return j;end;$$;
create or replace function greenloop_private.pf_lock(p_order uuid,p_revision integer) returns greenloop_private.parts_flow_orders language plpgsql security definer set search_path=pg_catalog,public as $$declare o greenloop_private.parts_flow_orders%rowtype;begin perform pg_advisory_xact_lock(19920261026);select * into o from greenloop_private.parts_flow_orders where id=p_order for update;if not found or not exists(select 1 from public.jobs j join public.devices d on d.id=j.device_id where j.id=o.job_id and j.deleted_at is null and d.deleted_at is null)then raise exception 'Parts order is unavailable.' using errcode='22023';end if;if p_revision is distinct from o.revision then raise exception 'The list changed. Refresh before continuing.' using errcode='40001';end if;return o;end;$$;
create or replace function greenloop_private.pf_guard() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$declare j_old uuid;r jsonb:=case when tg_op='DELETE' then to_jsonb(old)else to_jsonb(new)end;j uuid;s uuid;begin
 if exists(select 1 from greenloop_private.parts_flow_context where pid=pg_backend_pid() and tx=txid_current() and actor=auth.uid())then if tg_op='DELETE'then return old;else return new;end if;end if;
 if tg_table_name in ('job_part_requests','lab_service_reviews','lab_manual_part_installations','initial_qc_part_requirements')then j:=(r->>'job_id')::uuid;
 elsif tg_table_name='device_location_history'then j:=(r->>'job_id')::uuid;if exists(select 1 from greenloop_private.parts_flow_orders where job_id=j or tg_op='UPDATE'and job_id=(to_jsonb(old)->>'job_id')::uuid)and not exists(select 1 from greenloop_private.capability_scope where backend_pid=pg_backend_pid()and transaction_id=txid_current()and user_id=auth.uid())then raise exception 'Department movement must use the authorised workflow.'using errcode='42501';end if;if tg_op='DELETE'then return old;else return new;end if;
 elsif tg_table_name in ('part_issue_transactions','part_installations')then select job_id into j from public.job_part_requests where id=(r->>'part_request_id')::uuid;
 elsif tg_table_name='job_work_order_steps' then
 select job_id into j from public.job_work_orders where id=(r->>'work_order_id')::uuid;
 if tg_op='UPDATE'and new.work_order_id is distinct from old.work_order_id and exists(select 1 from greenloop_private.parts_flow_orders o join public.job_work_orders w on w.job_id=o.job_id where w.id=old.work_order_id)then raise exception 'A protected work step cannot be moved to another phone.'using errcode='42501';end if;
 if exists(select 1 from greenloop_private.parts_flow_orders where job_id=j)and not exists(select 1 from greenloop_private.capability_scope where backend_pid=pg_backend_pid()and transaction_id=txid_current()and user_id=auth.uid())and(tg_op='DELETE'or tg_op='INSERT'and coalesce((r->>'rework_count')::integer,0)>greenloop_private.pf_cycle(j)or tg_op='UPDATE'and new.rework_count is distinct from old.rework_count)then raise exception 'Repair cycles can only change through the authorised workflow.'using errcode='42501';end if;
 if tg_op='DELETE'then return old;end if;
 if tg_op<>'UPDATE'or new.step_status is not distinct from old.step_status or new.step_status<>'completed'or new.department not in ('laboratory','glass')then return new;end if;raise exception 'Complete this phone through the finalised Parts workflow.'using errcode='42501';
 end if;
 if tg_op='UPDATE'then
 if tg_table_name in ('job_part_requests','lab_service_reviews','lab_manual_part_installations','initial_qc_part_requirements')then j_old:=(to_jsonb(old)->>'job_id')::uuid;elsif tg_table_name in ('part_issue_transactions','part_installations')then select job_id into j_old from public.job_part_requests where id=(to_jsonb(old)->>'part_request_id')::uuid;end if;
 if j_old is distinct from j and exists(select 1 from greenloop_private.parts_flow_orders where job_id=j_old)then raise exception 'An issued record cannot be moved to another phone.'using errcode='42501';end if;end if;
 if tg_table_name='part_issue_transactions'and tg_op='INSERT'and exists(select 1 from public.jobs where id=j and current_status in ('laboratory_pending','laboratory_in_progress','glass_pending','glass_in_progress'))then raise exception 'Finalise the Lab / Glass list and issue it from the new Parts page.'using errcode='42501';end if;
 if tg_table_name='lab_manual_part_installations'then raise exception 'Use the finalised Parts workflow for new parts.'using errcode='42501';end if;
 if exists(select 1 from greenloop_private.parts_flow_orders o where o.job_id=j and o.cycle=greenloop_private.pf_cycle(j))then raise exception 'Use the finalised Parts workflow. Issued lists cannot be changed; request a return.' using errcode='42501';end if;
 if tg_op='DELETE'then return old;else return new;end if;
end;$$;
do $$declare t text;begin foreach t in array array['job_part_requests','lab_service_reviews','lab_manual_part_installations','initial_qc_part_requirements','part_issue_transactions','part_installations','device_location_history']loop execute format('drop trigger if exists zz_parts_flow_guard on public.%I',t);execute format('create trigger zz_parts_flow_guard before insert or update or delete on public.%I for each row execute function greenloop_private.pf_guard()',t);end loop;drop trigger if exists zz_parts_flow_complete_guard on public.job_work_order_steps;create trigger zz_parts_flow_complete_guard before insert or update or delete on public.job_work_order_steps for each row execute function greenloop_private.pf_guard();end;$$;

create or replace function greenloop_private.pf_plan(p_step uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare j uuid;d uuid;wo uuid;o greenloop_private.parts_flow_orders%rowtype;parts jsonb;services jsonb;issues jsonb;returns jsonb;legacy boolean;v_start timestamptz;begin
 select w.job_id,w.device_id,w.id into j,d,wo from public.job_work_order_steps s join public.job_work_orders w on w.id=s.work_order_id join public.jobs job on job.id=w.job_id and job.deleted_at is null join public.devices dev on dev.id=w.device_id and dev.deleted_at is null where s.id=p_step and s.department in ('laboratory','glass');if j is null then return null;end if;
 select max(entered_at)into v_start from greenloop_private.lab_stays_v1(d)where job_id=j;
 select * into o from greenloop_private.parts_flow_orders where job_id=j and cycle=greenloop_private.pf_cycle(j);
 select exists(select 1 from public.part_issue_transactions i join public.job_part_requests r on r.id=i.part_request_id where r.job_id=j and i.issued_at>=coalesce(v_start,'-infinity'::timestamptz) and not exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id))into legacy;
 if o.id is not null then
 select coalesce(jsonb_agg(jsonb_build_object('request_id',r.id,'name',r.part_name,'quantity',r.quantity_requested,'issued',r.quantity_issued,'returned',r.quantity_returned,'installed',r.quantity_installed)order by r.requested_at,r.id),'[]')into parts from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled';services:=o.services;
 else
 select coalesce(jsonb_agg(jsonb_build_object('request_id',r.id,'name',r.part_name,'quantity',r.quantity_requested,'issued',r.quantity_issued,'returned',r.quantity_returned,'installed',r.quantity_installed)order by r.requested_at,r.id),'[]')into parts from public.job_part_requests r where r.job_id=j and r.status<>'cancelled' and(r.quantity_issued=0 or exists(select 1 from public.part_issue_transactions i where i.part_request_id=r.id and i.issued_at>=coalesce(v_start,'-infinity'::timestamptz)))and not exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id);
 if jsonb_array_length(parts)=0 and greenloop_private.pf_cycle(j)<=1 then select coalesce(jsonb_agg(jsonb_build_object('name',q.part_name,'quantity',q.quantity_required,'issued',0,'returned',0,'installed',0)order by q.identified_at),'[]')into parts from public.initial_qc_part_requirements q where q.job_id=j and q.status not in ('not_required','cancelled','manually_installed','unused_returned');end if;
 select coalesce(jsonb_agg(jsonb_build_object('name',x.name,'status',case when legacy then 'confirmed'else 'pending'end)order by x.name),'[]')into services from(select distinct service_name name from public.lab_service_reviews where job_id=j and is_required and reviewed_at>=coalesce(v_start,'-infinity'::timestamptz)union select distinct f.check_item from public.initial_qc_findings f join public.job_work_orders w on w.initial_qc_inspection_id=f.inspection_id where w.id=wo and greenloop_private.pf_cycle(j)<=1 and public.is_initial_qc_service(f.check_item) and not exists(select 1 from public.lab_service_reviews r where r.work_order_step_id=p_step and r.initial_finding_id=f.id and not r.is_required))x;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('issue_id',i.id,'request_id',r.id,'name',r.part_name,'issued',i.quantity_issued,'returned',i.quantity_returned,'available',greatest(0,i.quantity_issued-i.quantity_returned-coalesce((select sum(quantity_installed)from public.part_installations where part_issue_id=i.id),0)-coalesce((select sum(quantity)from greenloop_private.parts_flow_returns where issue_id=i.id and status='pending'),0)-coalesce((select sum(quantity)from public.lab_part_return_requests where part_request_id=r.id and status='pending'),0)))order by i.issued_at,i.id),'[]')into issues from public.part_issue_transactions i join public.job_part_requests r on r.id=i.part_request_id where r.job_id=j and (o.id is null and not exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id)or exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id and m.order_id=o.id));
 select coalesce(jsonb_agg(jsonb_build_object('id',ret.id,'issue_id',ret.issue_id,'quantity',ret.quantity,'notes',ret.notes,'status',ret.status,'classification',ret.classification,'requested_at',ret.requested_at,'reviewed_at',ret.reviewed_at)order by ret.requested_at desc),'[]')into returns from greenloop_private.parts_flow_returns ret where ret.order_id=o.id;
 returns:=returns||coalesce((select jsonb_agg(jsonb_build_object('id',ret.id,'quantity',ret.quantity,'notes','Existing return awaiting Parts review','status','pending','legacy',true))from public.lab_part_return_requests ret where ret.job_id=j and ret.status='pending'),'[]');
 return jsonb_build_object('step_id',p_step,'order_id',o.id,'revision',coalesce(o.revision,0),'submitted',o.id is not null or legacy,'locked',o.first_issued_at is not null or legacy,'legacy',coalesce(o.legacy,legacy),'completed',o.completed_at is not null,'parts',parts,'services',services,'issues',issues,'returns',returns,'previous_manual_parts',coalesce((select jsonb_agg(jsonb_build_object('name',m.part_name,'quantity',m.quantity))from public.lab_manual_part_installations m where m.work_order_step_id=p_step),'[]'));
end;$$;

create or replace function public.get_lab_parts_plans_v1(p_step_ids uuid[]) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare result jsonb;begin perform greenloop_private.pf_cap('lab_glass','view');if p_step_ids is null or cardinality(p_step_ids)>250 then raise exception 'Select a valid technician list.'using errcode='22023';end if;select coalesce(jsonb_agg(plan),'[]')into result from(select greenloop_private.pf_plan(id)plan from(select distinct unnest(p_step_ids)id)x)y where plan is not null;return result;end;$$;

create or replace function public.submit_lab_parts_plan_v1(p_step_id uuid,p_revision integer,p_parts jsonb,p_services jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare j uuid;dev uuid;o greenloop_private.parts_flow_orders%rowtype;item jsonb;svc jsonb;name text;qty integer;rid uuid;keep uuid[]:='{}';v_services jsonb:='[]';prior jsonb;v_start timestamptz;begin
 perform greenloop_private.pf_cap('lab_glass','entry');j:=greenloop_private.pf_step(p_step_id);select device_id into dev from public.jobs where id=j;select max(entered_at)into v_start from greenloop_private.lab_stays_v1(dev)where job_id=j;
 if p_parts is null or jsonb_typeof(p_parts)<>'array' or jsonb_array_length(p_parts)>100 or p_services is null or jsonb_typeof(p_services)<>'array' or jsonb_array_length(p_services)>100 then raise exception 'Use valid parts and service lists.'using errcode='22023';end if;
 select * into o from greenloop_private.parts_flow_orders where job_id=j and cycle=greenloop_private.pf_cycle(j)for update;
 if p_revision is distinct from coalesce(o.revision,0)then raise exception 'The list changed. Refresh before submitting.'using errcode='40001';end if;
 if o.first_issued_at is not null or exists(select 1 from public.part_issue_transactions i join public.job_part_requests r on r.id=i.part_request_id where r.job_id=j and i.issued_at>=coalesce(v_start,'-infinity'::timestamptz)and not exists(select 1 from greenloop_private.parts_flow_requests m join greenloop_private.parts_flow_orders prev on prev.id=m.order_id where m.request_id=r.id and prev.cycle<greenloop_private.pf_cycle(j)))then raise exception 'Parts have been issued. The list is locked; request a return.'using errcode='22023';end if;
 if o.completed_at is not null then raise exception 'This order is completed.'using errcode='22023';end if;prior:=coalesce(to_jsonb(o),'{}');
 perform greenloop_private.pf_context(true);
 if o.id is null then insert into greenloop_private.parts_flow_orders(job_id,device_id,step_id,cycle,submitted_by)values(j,dev,p_step_id,greenloop_private.pf_cycle(j),auth.uid())returning * into o;else update greenloop_private.parts_flow_orders set revision=revision+1,step_id=p_step_id,submitted_at=now(),submitted_by=auth.uid()where id=o.id returning * into o;end if;
 for item in select value from jsonb_array_elements(p_parts)loop
 name:=regexp_replace(btrim(item->>'name'),'\s+',' ','g');if name is null or length(name)not between 1 and 120 or coalesce(item->>'quantity','')!~'^[0-9]{1,5}$' then raise exception 'Each part needs a name and a positive whole quantity.'using errcode='22023';end if;qty:=(item->>'quantity')::integer;if qty not between 1 and 10000 or exists(select 1 from public.job_part_requests r where r.id=any(keep)and lower(r.part_name)=lower(name))then raise exception 'Use one line per part with a valid quantity.'using errcode='22023';end if;
 select r.id into rid from public.job_part_requests r left join greenloop_private.parts_flow_requests m on m.request_id=r.id where r.job_id=j and lower(regexp_replace(btrim(r.part_name),'\s+',' ','g'))=lower(name)and r.quantity_issued=0 and(m.order_id=o.id or m.request_id is null)order by r.requested_at,r.id limit 1;
 if rid is null then insert into public.job_part_requests(job_id,device_id,part_name,quantity_requested,request_source,requested_by)values(j,dev,name,qty,'technician_additional',auth.uid())returning id into rid;else update public.job_part_requests set part_name=name,quantity_requested=qty,status='requested',updated_at=now()where id=rid;end if;
 insert into greenloop_private.parts_flow_requests values(rid,o.id)on conflict(request_id)do nothing;keep:=array_append(keep,rid);
 end loop;
 update public.job_part_requests r set status='cancelled',updated_at=now()where r.job_id=j and r.quantity_issued=0 and not(r.id=any(keep))and (not exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id)or exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id and m.order_id=o.id));
 for item in select value from jsonb_array_elements(p_services)loop
 name:=regexp_replace(btrim(case when jsonb_typeof(item)='string'then item#>>'{}'else item->>'name'end),'\s+',' ','g');if name is null or length(name)not between 1 and 120 or exists(select 1 from jsonb_array_elements(v_services)x where lower(x->>'name')=lower(name))then raise exception 'Use one valid line per service.'using errcode='22023';end if;select value into svc from jsonb_array_elements(o.services)where lower(value->>'name')=lower(name);v_services:=v_services||jsonb_build_array(jsonb_build_object('name',name,'status',coalesce(svc->>'status','pending')));
 end loop;
 update greenloop_private.parts_flow_orders set services=v_services where id=o.id;
 -- Resolve QC planning without losing the original QC requirements.
 update public.initial_qc_part_requirements q set status=case when exists(select 1 from public.job_part_requests r where r.id=any(keep)and lower(r.part_name)=lower(q.part_name))then 'requested'else 'not_required'end,reviewed_by=auth.uid(),reviewed_at=now()where q.job_id=j and q.status in ('identified','requested','not_required');
 insert into greenloop_private.parts_flow_audit(order_id,action,actor,details)values(o.id,'requirements_submitted',auth.uid(),jsonb_build_object('previous',prior,'parts',p_parts,'services',v_services,'revision',o.revision));
 insert into public.device_events(device_id,job_id,event_type,event_title,event_data,actor_id)values(dev,j,'lab_parts_plan_submitted','Lab / Glass finalised parts and services for Parts',jsonb_build_object('parts',p_parts,'services',v_services,'revision',o.revision),auth.uid());perform greenloop_private.pf_context(false);return greenloop_private.pf_plan(p_step_id);
end;$$;
create or replace function greenloop_private.pf_status(p_order uuid)returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when o.completed_at is not null then 'Completed' when exists(select 1 from greenloop_private.parts_flow_returns r where r.order_id=o.id and r.status='pending')then 'Return Requested' when exists(select 1 from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled' and r.quantity_issued<r.quantity_requested)then case when o.first_issued_at is null then 'Sent to Parts'else 'Partially Issued'end when exists(select 1 from jsonb_array_elements(o.services)x where x->>'status'='pending')then 'Services Pending'else 'Issued'end from greenloop_private.parts_flow_orders o where o.id=p_order;$$;
create or replace function public.get_parts_flow_queue_v1(p_filters jsonb default '{}',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'submitted_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare f date;t date;s text;st text;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');
 if jsonb_typeof(p_filters)is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_filters)k where k not in ('_search','_from','_to','status'))or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 100 or p_sort_key is null or p_sort_key not in ('submitted_at','imei','model','status')or p_sort_direction is null or p_sort_direction not in ('asc','desc')then raise exception 'Select valid filters and sorting.'using errcode='22023';end if;
 if p_filters<>'{}'then perform greenloop_private.pf_cap('parts','search');end if;if p_sort_key<>'submitted_at' or p_sort_direction<>'desc'then perform greenloop_private.pf_cap('parts','sort');end if;
 f:=nullif(p_filters->>'_from','')::date;t:=nullif(p_filters->>'_to','')::date;s:=lower(btrim(coalesce(p_filters->>'_search','')));st:=nullif(p_filters->>'status','');if f>t or length(s)>120 then raise exception 'Select valid dates or search.'using errcode='22023';end if;
 with base as materialized(select o.id order_id,o.revision,o.submitted_at,d.imei_1 imei,d.model,d.storage_gb,d.color,j.job_number,greenloop_private.pf_status(o.id)status,coalesce((select s.assigned_technician_name from public.job_work_order_steps s where s.id=o.step_id),'Unassigned')technician_name,(select count(*)from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled')parts_count,jsonb_array_length(o.services)services_count from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null),q as materialized(select * from base where(f is null or(submitted_at at time zone 'Asia/Dubai')::date>=f)and(t is null or(submitted_at at time zone 'Asia/Dubai')::date<=t)and(s=''or strpos(lower(concat_ws(' ',imei,model,storage_gb,color,job_number,technician_name)),s)>0)and(st is null or status=st)),page as(select *from q order by case when p_sort_key='submitted_at'and p_sort_direction='asc'then submitted_at end asc,case when p_sort_key='submitted_at'and p_sort_direction='desc'then submitted_at end desc,case when p_sort_direction='asc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status end end asc,case when p_sort_direction='desc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status end end desc,order_id offset p_offset limit p_limit)
 select jsonb_build_object('legacy_returns',coalesce((select jsonb_agg(jsonb_build_object('id',lr.id,'imei',ld.imei_1,'name',lr.part_name,'quantity',lr.quantity,'reason',lr.return_reason,'at',lr.requested_at)order by lr.requested_at)from public.lab_part_return_requests lr join public.jobs lj on lj.id=lr.job_id and lj.deleted_at is null join public.devices ld on ld.id=lr.device_id and ld.deleted_at is null where lr.status='pending'),'[]'),'total',(select count(*)from q),'rows',coalesce((select jsonb_agg(to_jsonb(p))from page p),'[]'),'facets',jsonb_build_object('status',(select coalesce(jsonb_agg(distinct status),'[]')from base)))into result;return result;
end;$$;
create or replace function public.get_parts_flow_order_v1(p_order_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare o greenloop_private.parts_flow_orders%rowtype;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');select *into o from greenloop_private.parts_flow_orders where id=p_order_id;if not found or not exists(select 1 from public.jobs j join public.devices d on d.id=j.device_id where j.id=o.job_id and j.deleted_at is null and d.deleted_at is null)then raise exception 'Order unavailable.'using errcode='22023';end if;
 select jsonb_build_object('order_id',o.id,'revision',o.revision,'status',greenloop_private.pf_status(o.id),'locked',o.first_issued_at is not null,'submitted_at',o.submitted_at,'device',jsonb_build_object('imei',d.imei_1,'model',d.model,'storage_gb',d.storage_gb,'color',d.color),'parts',coalesce((select jsonb_agg(jsonb_build_object('request_id',r.id,'name',r.part_name,'quantity',r.quantity_requested,'issued',r.quantity_issued,'returned',r.quantity_returned,'stock',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'label',case when exists(select 1 from greenloop_private.parts_flow_stock z where z.inventory_id=i.id)then 'Usable returns'else i.sku end,'quantity',i.stock_quantity))from public.part_inventory i where i.is_active and i.stock_quantity>0 and lower(regexp_replace(btrim(i.part_name),'\s+',' ','g'))=lower(regexp_replace(btrim(r.part_name),'\s+',' ','g'))),'[]'))order by r.requested_at,r.id)from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled'),'[]'),'services',o.services,
 'issues',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'name',r.part_name,'quantity',i.quantity_issued,'returned',i.quantity_returned,'issued_at',i.issued_at,'unit_price',case when p.issue_id is not null then p.unit_price else i.unit_cost end,'currency',coalesce(p.currency,'AED'))order by i.issued_at desc,i.id)from public.part_issue_transactions i join public.job_part_requests r on r.id=i.part_request_id join greenloop_private.parts_flow_requests m on m.request_id=r.id left join greenloop_private.parts_flow_prices p on p.issue_id=i.id where m.order_id=o.id),'[]'),
 'returns',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'name',q.part_name,'quantity',r.quantity,'notes',r.notes,'status',r.status,'classification',r.classification,'replacement',r.replacement,'requested_at',r.requested_at,'reviewed_at',r.reviewed_at,'review_notes',r.review_notes)order by r.requested_at desc)from greenloop_private.parts_flow_returns r join public.part_issue_transactions i on i.id=r.issue_id join public.job_part_requests q on q.id=i.part_request_id where r.order_id=o.id),'[]'),
 'history',coalesce((select jsonb_agg(jsonb_build_object('action',a.action,'at',a.created_at,'by',u.full_name,'details',a.details)order by a.created_at desc,a.id)from greenloop_private.parts_flow_audit a left join public.user_profiles u on u.id=a.actor where a.order_id=o.id),'[]'))into result from public.devices d where d.id=o.device_id;return result;
end;$$;
create or replace function public.issue_parts_flow_v1(p_order_id uuid,p_revision integer,p_request_id uuid,p_quantity integer,p_unit_price numeric default null,p_stock_id uuid default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare o greenloop_private.parts_flow_orders%rowtype;r public.job_part_requests%rowtype;i uuid;issue uuid;key text;stock integer;begin
 perform greenloop_private.pf_cap('parts','issue');o:=greenloop_private.pf_lock(p_order_id,p_revision);
 if o.completed_at is not null or o.cycle<>greenloop_private.pf_cycle(o.job_id)or not exists(select 1 from public.jobs where id=o.job_id and current_status in ('laboratory_pending','laboratory_in_progress','glass_pending','glass_in_progress'))then raise exception 'This order is no longer active in Lab / Glass.'using errcode='22023';end if;
 if p_quantity is null or p_quantity not between 1 and 10000 or p_unit_price is not null and(p_unit_price<0 or p_unit_price>9999999999.99 or p_unit_price<>round(p_unit_price,2))then raise exception 'Use a positive whole quantity and an optional non-negative price with two decimal places.'using errcode='22023';end if;
 select q.*into r from public.job_part_requests q join greenloop_private.parts_flow_requests m on m.request_id=q.id where q.id=p_request_id and m.order_id=o.id and q.status<>'cancelled'for update of q;if r.id is null or p_quantity>r.quantity_requested-r.quantity_issued then raise exception 'Issue quantity exceeds this current requirement.'using errcode='22023';end if;
 perform greenloop_private.pf_context(true);
 if p_stock_id is not null then select id,stock_quantity into i,stock from public.part_inventory where id=p_stock_id and is_active and lower(regexp_replace(btrim(part_name),'\s+',' ','g'))=lower(regexp_replace(btrim(r.part_name),'\s+',' ','g'))for update;if i is null or stock<p_quantity then raise exception 'The selected stock is unavailable or is a different part.'using errcode='22023';end if;update public.part_inventory set stock_quantity=stock_quantity-p_quantity where id=i;
 else key:=lower(regexp_replace(btrim(r.part_name),'\s+',' ','g'));select inventory_id into i from greenloop_private.parts_flow_stock where part_key=key;if i is null then insert into public.part_inventory(sku,part_name,stock_quantity,unit_cost,notes,created_by)values('PF-'||md5(key),r.part_name,0,0,'Parts supplied directly; usable returned quantities are held here.',auth.uid())returning id into i;insert into greenloop_private.parts_flow_stock values(key,i);end if;end if;
 -- Public stock ledgers carry no new issue price. Actual optional prices are private.
 insert into public.part_issue_transactions(part_request_id,inventory_part_id,quantity_issued,unit_cost,issue_notes,issued_by)values(r.id,i,p_quantity,0,'Issued by Parts Flow; any price is restricted to Parts.',auth.uid())returning id into issue;
 insert into greenloop_private.parts_flow_prices(issue_id,order_id,unit_price)values(issue,o.id,p_unit_price);
 update public.job_part_requests set quantity_issued=quantity_issued+p_quantity,status=case when quantity_issued+p_quantity>=quantity_requested then 'issued'else 'partially_issued'end,updated_at=now()where id=r.id;
 update greenloop_private.parts_flow_orders set first_issued_at=coalesce(first_issued_at,now()),revision=revision+1 where id=o.id;
 insert into greenloop_private.parts_flow_audit(order_id,action,actor,details)values(o.id,'part_issued',auth.uid(),jsonb_build_object('part',r.part_name,'quantity',p_quantity,'issue_id',issue));
 insert into public.device_events(device_id,job_id,event_type,event_title,event_data,actor_id)values(o.device_id,o.job_id,'parts_flow_issued','Parts issued; Lab / Glass requirement list locked',jsonb_build_object('part_name',r.part_name,'quantity',p_quantity),auth.uid());perform greenloop_private.pf_context(false);return jsonb_build_object('issued',true,'issue_id',issue);
end;$$;
create or replace function public.set_parts_flow_service_v1(p_order_id uuid,p_revision integer,p_name text,p_status text)returns boolean language plpgsql security definer set search_path=pg_catalog,public as $$declare o greenloop_private.parts_flow_orders%rowtype;begin perform greenloop_private.pf_cap('parts','edit');o:=greenloop_private.pf_lock(p_order_id,p_revision);if o.completed_at is not null or p_status is null or p_status not in ('pending','confirmed','completed')or not exists(select 1 from jsonb_array_elements(o.services)x where x->>'name'=p_name)then raise exception 'Select a current service and valid status.'using errcode='22023';end if;update greenloop_private.parts_flow_orders set services=(select jsonb_agg(case when x->>'name'=p_name then jsonb_set(x,'{status}',to_jsonb(p_status))else x end)from jsonb_array_elements(o.services)x),revision=revision+1 where id=o.id;insert into greenloop_private.parts_flow_audit(order_id,action,actor,details)values(o.id,'service_status',auth.uid(),jsonb_build_object('service',p_name,'status',p_status));return true;end;$$;

create or replace function public.request_parts_flow_return_v1(p_step_id uuid,p_revision integer,p_issue_id uuid,p_quantity integer,p_notes text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare j uuid;o greenloop_private.parts_flow_orders%rowtype;req public.job_part_requests%rowtype;iss public.part_issue_transactions%rowtype;available integer;ret uuid;plan jsonb;begin
 perform greenloop_private.pf_cap('lab_glass','entry');j:=greenloop_private.pf_step(p_step_id);select *into o from greenloop_private.parts_flow_orders where job_id=j and cycle=greenloop_private.pf_cycle(j)for update;
 if p_revision is distinct from coalesce(o.revision,0)then raise exception 'The list changed. Refresh before returning a part.'using errcode='40001';end if;
 if p_quantity is null or p_quantity not between 1 and 10000 or length(btrim(coalesce(p_notes,'')))not between 2 and 1000 then raise exception 'Enter a return quantity and notes for Parts to review.'using errcode='22023';end if;
 select i.*into iss from public.part_issue_transactions i join public.job_part_requests r on r.id=i.part_request_id where i.id=p_issue_id and r.job_id=j for update of i;select *into req from public.job_part_requests where id=iss.part_request_id;
 if iss.id is null or(o.id is not null and not exists(select 1 from greenloop_private.parts_flow_requests m where m.order_id=o.id and m.request_id=req.id))then raise exception 'Select an issued part from this repair cycle.'using errcode='22023';end if;
 available:=iss.quantity_issued-iss.quantity_returned-coalesce((select sum(quantity_installed)from public.part_installations where part_issue_id=iss.id),0)-coalesce((select sum(quantity)from greenloop_private.parts_flow_returns where issue_id=iss.id and status='pending'),0)-coalesce((select sum(quantity)from public.lab_part_return_requests where part_request_id=req.id and status='pending'),0);
 if available<p_quantity then raise exception 'Return quantity exceeds the unused, unreserved issued quantity.'using errcode='22023';end if;
 if o.id is null then plan:=greenloop_private.pf_plan(p_step_id);insert into greenloop_private.parts_flow_orders(job_id,device_id,step_id,cycle,submitted_by,first_issued_at,legacy,services)values(j,req.device_id,p_step_id,greenloop_private.pf_cycle(j),auth.uid(),iss.issued_at,true,plan->'services')returning *into o;insert into greenloop_private.parts_flow_requests select r.id,o.id from public.job_part_requests r where r.job_id=j and not exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id);end if;
 insert into greenloop_private.parts_flow_returns(order_id,issue_id,quantity,notes,requested_by)values(o.id,iss.id,p_quantity,btrim(p_notes),auth.uid())returning id into ret;update greenloop_private.parts_flow_orders set revision=revision+1 where id=o.id;
 insert into greenloop_private.parts_flow_audit(order_id,action,actor,details)values(o.id,'return_requested',auth.uid(),jsonb_build_object('part',req.part_name,'quantity',p_quantity,'notes',btrim(p_notes),'return_id',ret));insert into public.device_events(device_id,job_id,event_type,event_title,event_data,actor_id)values(req.device_id,j,'parts_flow_return_requested','Lab / Glass requested a Parts return review',jsonb_build_object('part_name',req.part_name,'quantity',p_quantity,'notes',btrim(p_notes)),auth.uid());return jsonb_build_object('return_id',ret,'status','pending');
end;$$;
create or replace function public.review_parts_flow_return_v1(p_order_id uuid,p_revision integer,p_return_id uuid,p_approve boolean,p_classification text default null,p_replacement boolean default false,p_notes text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public as $$declare o greenloop_private.parts_flow_orders%rowtype;ret greenloop_private.parts_flow_returns%rowtype;iss public.part_issue_transactions%rowtype;r public.job_part_requests%rowtype;available integer;begin
 perform greenloop_private.pf_cap('parts','return');o:=greenloop_private.pf_lock(p_order_id,p_revision);select *into ret from greenloop_private.parts_flow_returns where id=p_return_id and order_id=o.id and status='pending'for update;if ret.id is null or p_approve is null or length(coalesce(p_notes,''))>1000 then raise exception 'Select a pending return.'using errcode='22023';end if;
 if p_approve and(p_classification is null or p_classification not in ('not_needed','damaged','faulty')or p_replacement is null or(p_classification='not_needed'and p_replacement))then raise exception 'Parts must classify the return and select whether replacement is required.'using errcode='22023';end if;
 if p_approve and p_replacement and not exists(select 1 from public.jobs where id=o.job_id and current_status in ('laboratory_pending','laboratory_in_progress','glass_pending','glass_in_progress'))then raise exception 'Send the phone back to Lab / Glass before requesting a replacement.'using errcode='22023';end if;
 perform greenloop_private.pf_context(true);
 if p_approve then
 select *into iss from public.part_issue_transactions where id=ret.issue_id for update;select *into r from public.job_part_requests where id=iss.part_request_id for update;available:=iss.quantity_issued-iss.quantity_returned-coalesce((select sum(quantity_installed)from public.part_installations where part_issue_id=iss.id),0);if ret.quantity>available then raise exception 'This issued quantity is no longer returnable.'using errcode='22023';end if;
 update public.part_issue_transactions set quantity_returned=quantity_returned+ret.quantity,returned_by=auth.uid(),returned_at=now(),return_notes=p_classification||': '||coalesce(p_notes,''),status=case when quantity_returned+ret.quantity>=quantity_issued then 'returned'else 'partially_returned'end where id=iss.id;
 if p_classification='not_needed'then update public.part_inventory set stock_quantity=stock_quantity+ret.quantity where id=iss.inventory_part_id;end if;
 update public.job_part_requests set quantity_returned=quantity_returned+ret.quantity,quantity_requested=quantity_requested+case when p_replacement then ret.quantity else 0 end,status=case when p_replacement then 'partially_issued'when quantity_installed+quantity_returned+ret.quantity>=quantity_requested then 'unused_returned'else status end,updated_at=now()where id=r.id;
 insert into public.part_return_audit(part_issue_id,part_request_id,inventory_part_id,job_id,device_id,imei,device_number,job_number,supplier_code,part_name,quantity,return_condition,reason,unit_cost,returned_by)select iss.id,r.id,iss.inventory_part_id,j.id,j.device_id,d.imei_1,d.device_number,j.job_number,s.supplier_code,r.part_name,ret.quantity,case when p_classification='not_needed'then 'restocked'else p_classification end,coalesce(p_notes,p_classification),iss.unit_cost,auth.uid()from public.jobs j join public.devices d on d.id=j.device_id left join public.suppliers s on s.id=j.supplier_id where j.id=r.job_id;
 end if;
 update greenloop_private.parts_flow_returns set status=case when p_approve then 'approved'else 'rejected'end,classification=case when p_approve then p_classification end,replacement=p_approve and coalesce(p_replacement,false),reviewed_by=auth.uid(),reviewed_at=now(),review_notes=nullif(btrim(p_notes),'')where id=ret.id;update greenloop_private.parts_flow_orders set revision=revision+1 where id=o.id;
 insert into greenloop_private.parts_flow_audit(order_id,action,actor,details)values(o.id,'return_reviewed',auth.uid(),jsonb_build_object('return_id',ret.id,'approved',p_approve,'classification',p_classification,'replacement',p_replacement,'notes',p_notes));insert into public.device_events(device_id,job_id,event_type,event_title,event_data,actor_id)values(o.device_id,o.job_id,'parts_flow_return_reviewed','Parts reviewed the returned part',jsonb_build_object('quantity',ret.quantity,'approved',p_approve,'reason',p_classification,'replacement',p_replacement),auth.uid());perform greenloop_private.pf_context(false);return true;
end;$$;
create or replace function public.complete_parts_flow_lab_v1(p_step_id uuid,p_revision integer)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare j uuid;o greenloop_private.parts_flow_orders%rowtype;result jsonb;begin
 perform greenloop_private.pf_cap('lab_glass','entry');j:=greenloop_private.pf_step(p_step_id);select *into o from greenloop_private.parts_flow_orders where job_id=j and cycle=greenloop_private.pf_cycle(j)for update;
 if p_revision is distinct from coalesce(o.revision,0)then raise exception 'Parts changed. Refresh before completing this phone.'using errcode='40001';end if;
 if o.id is null and coalesce((greenloop_private.pf_plan(p_step_id)->>'legacy')::boolean,false)then if exists(select 1 from public.lab_part_return_requests where job_id=j and status='pending')then raise exception 'Wait for the existing Parts return review.'using errcode='22023';end if;return public.complete_lab_technician_line(p_step_id);end if;
 if o.id is null then raise exception 'Send the final parts and services list to Parts first, including an empty list when no work is required.'using errcode='22023';end if;
 if exists(select 1 from greenloop_private.parts_flow_returns where order_id=o.id and status='pending')or exists(select 1 from public.lab_part_return_requests where job_id=j and status='pending')or exists(select 1 from jsonb_array_elements(o.services)x where x->>'status'='pending')or exists(select 1 from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled'and r.quantity_issued<r.quantity_requested)then raise exception 'Wait for Parts, service confirmation and all return reviews before completing the phone.'using errcode='22023';end if;
 perform greenloop_private.pf_context(true);result:=public.complete_lab_technician_line(p_step_id);update greenloop_private.parts_flow_orders set completed_at=now(),revision=revision+1,services=coalesce((select jsonb_agg(jsonb_set(x,'{status}','"completed"'))from jsonb_array_elements(o.services)x),'[]')where id=o.id;insert into greenloop_private.parts_flow_audit(order_id,action,actor)values(o.id,'lab_completed',auth.uid());perform greenloop_private.pf_context(false);return result;
end;$$;
create or replace function public.get_parts_flow_counts_v1()returns integer language plpgsql stable security definer set search_path=pg_catalog,public as $$begin perform greenloop_private.require_office_network();if auth.uid()is null or not public.is_active_staff()or greenloop_private.damage_tv_only(auth.uid())then raise exception 'Active staff access required.'using errcode='42501';end if;return(select count(*)::integer from(select o.job_id from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null where greenloop_private.pf_status(o.id)in ('Sent to Parts','Partially Issued','Services Pending','Return Requested')union select r.job_id from public.lab_part_return_requests r join public.jobs j on j.id=r.job_id and j.deleted_at is null join public.devices d on d.id=r.device_id and d.deleted_at is null where r.status='pending')waiting);end;$$;
create or replace function public.review_legacy_parts_return_v1(p_return_id uuid,p_approve boolean,p_classification text default null,p_replacement boolean default false,p_notes text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public as $$declare ret public.lab_part_return_requests%rowtype;o greenloop_private.parts_flow_orders%rowtype;i public.part_issue_transactions%rowtype;v_return_id uuid;plan jsonb;begin
 perform greenloop_private.pf_cap('parts','return');perform pg_advisory_xact_lock(19920261026);select *into ret from public.lab_part_return_requests where id=p_return_id and status='pending'for update;if ret.id is null then raise exception 'This existing return has already been reviewed.'using errcode='22023';end if;
 select iss.*into i from public.part_issue_transactions iss where iss.part_request_id=ret.part_request_id and(not coalesce(p_approve,false)or iss.quantity_issued-iss.quantity_returned-coalesce((select sum(quantity_installed)from public.part_installations where part_issue_id=iss.id),0)-coalesce((select sum(quantity)from greenloop_private.parts_flow_returns where issue_id=iss.id and status='pending'),0)>=ret.quantity) order by iss.issued_at,iss.id limit 1 for update of iss;if i.id is null then raise exception 'The issued quantity is no longer available for this return.'using errcode='22023';end if;
 select *into o from greenloop_private.parts_flow_orders where job_id=ret.job_id and cycle=greenloop_private.pf_cycle(ret.job_id)for update;
 if o.id is null then plan:=greenloop_private.pf_plan(ret.work_order_step_id);insert into greenloop_private.parts_flow_orders(job_id,device_id,step_id,cycle,submitted_by,first_issued_at,legacy,services)values(ret.job_id,ret.device_id,ret.work_order_step_id,greenloop_private.pf_cycle(ret.job_id),ret.requested_by,i.issued_at,true,coalesce(plan->'services','[]'))returning *into o;insert into greenloop_private.parts_flow_requests select r.id,o.id from public.job_part_requests r where r.job_id=ret.job_id and not exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id);end if;
 insert into greenloop_private.parts_flow_returns(order_id,issue_id,quantity,notes,requested_by,requested_at)values(o.id,i.id,ret.quantity,'Existing return: '||ret.return_reason,ret.requested_by,ret.requested_at)returning parts_flow_returns.id into v_return_id;
 perform public.review_parts_flow_return_v1(o.id,o.revision,v_return_id,p_approve,p_classification,p_replacement,p_notes);update public.lab_part_return_requests set status=case when p_approve then 'approved'else 'rejected'end,return_reason=case when p_approve then p_classification else return_reason end,reviewed_by=auth.uid(),reviewed_at=now(),review_notes=p_notes where lab_part_return_requests.id=ret.id;return true;
end;$$;
-- Existing authorised IMEI reset retains its exact permission, preview and code
-- checks, and receives a private transaction capability for the new guards.
do $reset$declare sig text;impl text;ddl text;name text;begin
 sig:='public.execute_greenloop_deletion(text,text,text,text,text,text)';select implementation into impl from greenloop_private.office_routines where to_regprocedure(identity)=to_regprocedure(sig);if impl is null then raise exception 'Reviewed reset entry point is missing.';end if;select pg_get_functiondef(to_regprocedure(impl))into ddl;
 if strpos(ddl,'parts-flow-reset-199')=0 then
 select proname into name from pg_proc where oid=to_regprocedure(impl);execute regexp_replace(ddl,'FUNCTION greenloop_private\.'||name||'\(','FUNCTION greenloop_private.pf_reset_impl(');
 execute format('create or replace function greenloop_private.%I(p_scope text,p_imei text,p_deletion_code text,p_confirmation text,p_reason text,p_selection_token text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public set lock_timeout=''5s'' set statement_timeout=''90s''as %L',name,'declare result jsonb;begin -- parts-flow-reset-199
 perform greenloop_private.pf_context(true);result:=greenloop_private.pf_reset_impl(p_scope,p_imei,p_deletion_code,p_confirmation,p_reason,p_selection_token);perform greenloop_private.pf_context(false);return result;end;');
 update greenloop_private.office_routines set original_hash=md5(pg_get_functiondef(to_regprocedure(impl)))where to_regprocedure(identity)=to_regprocedure(sig);
 end if;
 revoke all on function greenloop_private.pf_reset_impl(text,text,text,text,text,text)from public,anon,authenticated;
end;$reset$;

-- Existing issued active jobs keep their original requests, issues and prices.
-- Private tracking locks those lists immediately without rewriting history.
do $legacy$declare x record;p jsonb;o uuid;begin
 for x in select distinct on(w.job_id) w.job_id,w.device_id,s.id step_id from public.job_work_orders w join public.job_work_order_steps s on s.work_order_id=w.id and s.department in ('laboratory','glass')and s.step_status='in_progress' join public.jobs j on j.id=w.job_id and j.deleted_at is null join public.devices d on d.id=w.device_id and d.deleted_at is null where j.current_status in ('laboratory_pending','laboratory_in_progress','glass_pending','glass_in_progress')and not exists(select 1 from greenloop_private.parts_flow_orders o where o.job_id=w.job_id and o.cycle=greenloop_private.pf_cycle(w.job_id))and exists(select 1 from public.job_part_requests r join public.part_issue_transactions i on i.part_request_id=r.id where r.job_id=w.job_id and not exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id))order by w.job_id,s.created_at desc,s.id loop
 p:=greenloop_private.pf_plan(x.step_id);insert into greenloop_private.parts_flow_orders(job_id,device_id,step_id,cycle,legacy,first_issued_at,submitted_at,services)select x.job_id,x.device_id,x.step_id,greenloop_private.pf_cycle(x.job_id),true,min(i.issued_at),min(i.issued_at),coalesce(p->'services','[]')from public.job_part_requests r join public.part_issue_transactions i on i.part_request_id=r.id where r.job_id=x.job_id returning id into o;insert into greenloop_private.parts_flow_requests select r.id,o from public.job_part_requests r where r.job_id=x.job_id and not exists(select 1 from greenloop_private.parts_flow_requests m where m.request_id=r.id);insert into greenloop_private.parts_flow_audit(order_id,action,details)values(o,'existing_issued_list_preserved',jsonb_build_object('original_records_changed',false));
 end loop;
end;$legacy$;

