insert into greenloop_private.capability_rpc_rules values('submit_lab_parts_plan_v1','{"page":"lab_glass","capability":"entry"}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_flow_queue_v1','{"page":"parts","capability":"view","read":true}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_flow_order_v1','{"page":"parts","capability":"view","read":true}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('issue_parts_flow_v1','{"page":"parts","capability":"issue"}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
