insert into greenloop_private.capability_rpc_rules values('request_parts_flow_return_v1','{"page":"lab_glass","capability":"entry"}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('review_parts_flow_return_v1','{"page":"parts","capability":"return"}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('complete_parts_flow_lab_v1','{"page":"lab_glass","capability":"entry"}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_flow_counts_v1','{"any":[{"page":"parts","capability":"view","read":true},{"page":"lab_glass","capability":"view","read":true},{"page":"overview","capability":"view","read":true}]}'::jsonb) on conflict(rpc_name) do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r) order by rpc_name)::text) from greenloop_private.capability_rpc_rules r) where identity='rules';
-- Register the added APIs with the existing office boundary and its audit snapshots.
do $wrap$declare f record;impl text;impl_identity text;args text;body text;begin
 for f in select p.*,pg_get_functiondef(p.oid) ddl,p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('review_legacy_parts_return_v1','get_lab_parts_plans_v1','submit_lab_parts_plan_v1','get_parts_flow_queue_v1','get_parts_flow_order_v1','issue_parts_flow_v1','set_parts_flow_service_v1','request_parts_flow_return_v1','review_parts_flow_return_v1','complete_parts_flow_lab_v1','get_parts_flow_counts_v1') loop
  impl:='office_impl_'||f.oid;execute regexp_replace(f.ddl,'FUNCTION public\.'||f.proname||'\(','FUNCTION greenloop_private.'||impl||'(');
  impl_identity:='greenloop_private.'||impl||'('||oidvectortypes(f.proargtypes)||')';execute format('revoke all on function %s from public,anon,authenticated',impl_identity);
  select coalesce(string_agg('$'||i,',' order by i),'') into args from generate_series(1,f.pronargs)i;
  body:=E'begin\n -- greenloop-office-wrapper-196\n perform greenloop_private.require_office_network();\n return greenloop_private.'||impl||'('||args||E');\nend;';
  execute format('create or replace function public.%I(%s) returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's' then 'stable' else 'volatile' end,body);
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);
  insert into greenloop_private.office_routines values(f.signature,impl_identity,md5(pg_get_functiondef(impl_identity::regprocedure)),md5(pg_get_functiondef(f.oid))) on conflict(identity) do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
 end loop;
 for f in select p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='greenloop_private'::regnamespace and p.proname like 'pf_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);end loop;
end;$wrap$;
create table if not exists greenloop_private.parts_flow_installation(identity text primary key,hash text not null);
alter table greenloop_private.parts_flow_installation enable row level security;
revoke all on greenloop_private.parts_flow_installation from public,anon,authenticated;
insert into greenloop_private.parts_flow_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid)) from pg_proc p where (p.pronamespace='public'::regnamespace and p.proname in ('review_legacy_parts_return_v1','get_lab_parts_plans_v1','submit_lab_parts_plan_v1','get_parts_flow_queue_v1','get_parts_flow_order_v1','issue_parts_flow_v1','set_parts_flow_service_v1','request_parts_flow_return_v1','review_parts_flow_return_v1','complete_parts_flow_lab_v1','get_parts_flow_counts_v1')) or(p.pronamespace='greenloop_private'::regnamespace and p.proname like 'pf_%') on conflict(identity) do update set hash=excluded.hash;
create or replace function public.get_parts_flow_version() returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_office_access_version()='20261024-office-access-1' and public.get_lab_delay_version()='20261024-lab-delay-1'
 and (select count(*)=20 and bool_and(hash=md5(pg_get_functiondef(to_regprocedure(identity)))) from greenloop_private.parts_flow_installation)
 and not has_table_privilege('authenticated','greenloop_private.parts_flow_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
 and not exists(select 1 from greenloop_private.parts_flow_installation where identity like 'greenloop_private.%' and (has_function_privilege('authenticated',to_regprocedure(identity),'EXECUTE') or has_function_privilege('anon',to_regprocedure(identity),'EXECUTE')))
 and not exists(select 1 from unnest(array['parts_flow_orders','parts_flow_requests','parts_flow_prices','parts_flow_returns','parts_flow_stock','parts_flow_audit','parts_flow_context'])t where has_table_privilege('authenticated','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_table_privilege('anon','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'))
 and (select count(*)=8 from pg_trigger where tgname in ('zz_parts_flow_guard','zz_parts_flow_complete_guard')and tgfoid='greenloop_private.pf_guard()'::regprocedure and tgenabled='O')
 then '20261026-parts-flow-1' end;$$;
revoke all on function public.get_parts_flow_version() from public;grant execute on function public.get_parts_flow_version() to anon,authenticated;
do $$begin if public.get_parts_flow_version() is distinct from '20261026-parts-flow-1' then raise exception 'Parts Flow installation verification failed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_parts_flow_version() as installed_parts_flow_version;
